{"relative_path":"factory/temp/src2/agents.py","content":"from typing import Any


def _format_string_value(val: str) -> str:
    return val.strip()


def _format_list_value(val: list) -> str:
    items = [_format_advisory_value(item) for item in val if item]
    return "\n".join(f"- {item}" for item in items if item)


def _format_dict_value(val: dict) -> str:
    sub_parts = []
    for k, v in val.items():
        formatted = _format_advisory_value(v)
        if formatted:
            sub_parts.append(f"{k.capitalize()}:\n{formatted}")
    return "\n\n".join(sub_parts)


def _format_advisory_value(val: Any) -> str:
    match val:
        case str():
            return _format_string_value(val)
        case list():
            return _format_list_value(val)
        case dict():
            return _format_dict_value(val)
        case _:
            return ""


def _format_advisory_dict(advisory: dict) -> str | None:
    parts = []
    for domain, text in advisory.items():
        formatted = _format_advisory_value(text)
        if formatted:
            parts.append(f"{domain.capitalize()}:\n{formatted}")
    return "\n\n".join(parts) if parts else None


def _get_advisory_narrative(advisory: Any) -> str | None:
    match advisory:
        case str() if advisory.strip():
            return advisory.strip()
        case dict():
            return _format_advisory_dict(advisory)
        case _:
            return None


def _get_rationale_narrative(rationale: Any) -> str | None:
    if isinstance(rationale, str) and rationale.strip():
        return rationale.strip()
    return None


class Agent:
    def __init__(self, advisory: Any = None, rationale: Any = None):
        self.advisory = advisory
        self.rationale = rationale

    def _get_module_6a_content(self) -> str:
        return "Default Module 6A Content"

    def _get_fallback_narrative(self) -> str | None:
        adv = _get_advisory_narrative(self.advisory)
        if adv is not None:
            return adv
        rat = _get_rationale_narrative(self.rationale)
        if rat is not None:
            return rat
        return self._get_module_6a_content()
