from typing import Any


class ForecastStore:
    def __init__(self):
        self.store = {}

    def _save_forecast(self, date_key: str, data: dict) -> None:
        self.store[date_key] = data

    def _synthesize_and_save_daily_forecast(
        self, target_date: date | str, raw_data: list[dict], metadata: dict | None = None
    ) -> dict:
        date_key = _format_date_key(target_date)
        synthesized = _synthesize_raw_data(raw_data)
        if isinstance(metadata, dict) and metadata:
            synthesized["_meta"] = metadata

        self._save_forecast(date_key, synthesized)
        return synthesized


def _format_date_key(target_date: date | str) -> str:
    match target_date:
        case date():
            return target_date.isoformat()
        case str() if target_date:
            return target_date
        case _:
            raise ValueError("Invalid target date")


def _synthesize_raw_data(raw_data: list[dict]) -> dict:
    synthesized = {}
    for item in raw_data:
        if isinstance(item, dict):
            metric = item.get("metric")
            val = item.get("value")
            if metric and val is not None:
                synthesized[metric] = val
    return synthesized


def _get_events(scored: Any) -> list:
    if isinstance(scored, dict):
        return scored.get("events") or []
    return getattr(scored, "events", []) or []


def _get_event_triggers(event: Any) -> list:
    if isinstance(event, dict):
        return event.get("triggers") or []
    if hasattr(event, "triggers"):
        return getattr(event, "triggers") or []
    return []


def _extract_trigger_labels(scored: dict) -> list[str]:
    events = _get_events(scored)
    triggers = set()
    for event in events:
        triggers.update(_get_event_triggers(event))
    return sorted(triggers)
"}

{"relative_path":"factory/temp/src2/billing.py","content":"from typing import Any

PROMO_DISCOUNTS = {
    "SAVE10": 0.10,
    "SAVE20": 0.20,
    "WELCOME50": 0.50,
}


def _check_promo_prefix(code: str) -> bool:
    return code.startswith(("SAVE", "WELCOME"))


def _check_promo_length(code: str) -> bool:
    return 6 <= len(code) <= 12


def _check_promo_registered(code: str) -> bool:
    return code in PROMO_DISCOUNTS


def validate_promo_code(code: str | None) -> bool:
    if not code:
        return False

    code = code.strip().upper()
    if not _check_promo_prefix(code):
        return False
    if not _check_promo_length(code):
        return False
    if not _check_promo_registered(code):
        return False

    return True
"}
